import { useCallback, useEffect, useState } from 'react';
import Head from 'next/head';
import { Bar, BarChart, CartesianGrid, Legend, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { adminFetch, apiErrorMessage, toQuery } from '@/lib/admin-client';

const today = new Date().toISOString().slice(0, 10);
const monthAgo = new Date(Date.now() - 30 * 86400000).toISOString().slice(0, 10);
type Funnel = { channels: Array<{ channel: string; registered: number; verified: number; first_booking: number; repeat: number; conv_verified_pct: number | null; conv_first_pct: number | null; conv_repeat_pct: number | null }> };
type Cohorts = { cohorts: Array<{ cohort: string; size: number; d1: number; d7: number; d30: number; ltv_avg_payers: number; payers: number }> };
type League = Array<{ kind: string; provider_id: string; provider_name: string; total: number; cancelled: number; completed: number; gmv: number; cancel_rate_pct: number; completion_rate_pct: number; avg_rating: number | null; ratings_count: number }>;
type Search = { top_queries: Array<{ _id: string; count: number; domain?: string }>; zero_result_opportunities: Array<{ _id: string; count: number; domain?: string }> };
type Nps = { total: number; promoters: number; passives: number; detractors: number; nps: number | null; distribution: Record<string, number> };
type Anomalies = { window_days: number; cancellation_anomalies: Array<{ date: string; value: number; z: number; direction: string }>; payment_failure_anomalies: Array<{ date: string; value: number; z: number; direction: string }> };

export default function AnalyticsSuitePage() {
  const [from, setFrom] = useState(monthAgo); const [to, setTo] = useState(today); const [domain, setDomain] = useState('');
  const [funnel, setFunnel] = useState<Funnel | null>(null); const [cohorts, setCohorts] = useState<Cohorts | null>(null); const [league, setLeague] = useState<League>([]); const [search, setSearch] = useState<Search | null>(null); const [nps, setNps] = useState<Nps | null>(null); const [anomalies, setAnomalies] = useState<Anomalies | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const load = useCallback(async () => { setLoading(true); setError(''); try { const suffix = toQuery({ from, to }); const [f, c, l, s, n, a] = await Promise.all([adminFetch<Funnel>(`/analytics-suite/funnels${suffix}`), adminFetch<Cohorts>(`/analytics-suite/cohorts${suffix}`), adminFetch<League>(`/analytics-suite/provider-league${toQuery({ from, to, domain })}`), adminFetch<Search>(`/analytics-suite/search${suffix}`), adminFetch<Nps>(`/analytics-suite/nps${suffix}`), adminFetch<Anomalies>('/analytics-suite/anomalies?days=45')]); setFunnel(f); setCohorts(c); setLeague(l); setSearch(s); setNps(n); setAnomalies(a); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تحميل التحليلات.')); } finally { setLoading(false); } }, [from, to, domain]);
  useEffect(() => { void load(); }, [load]);
  return <><Head><title>التحليلات | نبض</title></Head><section dir="rtl" className="space-y-6 p-6 md:p-8"><header><h1 className="text-3xl font-bold">حزمة التحليلات</h1><p className="mt-1 text-sm text-slate-500">كل مؤشرات التحويل والاحتفاظ والجودة مبنية من تجميعات Mongo في backend.</p></header><div className="grid gap-3 rounded-2xl border bg-white p-4 shadow-sm md:grid-cols-4"><label className="text-xs text-slate-500">من<input type="date" value={from} max={to} onChange={(e) => setFrom(e.target.value)} className="mt-1 w-full rounded-lg border p-2 text-sm"/></label><label className="text-xs text-slate-500">إلى<input type="date" value={to} min={from} max={today} onChange={(e) => setTo(e.target.value)} className="mt-1 w-full rounded-lg border p-2 text-sm"/></label><label className="text-xs text-slate-500">عمودي المزود<select value={domain} onChange={(e) => setDomain(e.target.value)} className="mt-1 w-full rounded-lg border p-2 text-sm"><option value="">الكل</option><option value="pharmacy">الصيدلية</option><option value="lab">المختبر</option><option value="radiology">الأشعة</option><option value="nursing">التمريض</option><option value="consultation">الاستشارات</option></select></label><button onClick={() => void load()} className="self-end rounded-lg bg-teal-700 px-4 py-2 text-sm font-bold text-white">تحديث</button></div>{error ? <p role="alert" className="rounded-lg bg-rose-50 p-3 text-rose-700">{error}</p> : null}{loading ? <p className="rounded-2xl border bg-white p-10 text-center text-slate-500">جارٍ إنشاء التجميعات…</p> : <><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">مسارات التحويل بحسب القناة</h2><div className="mt-4 h-80"><ResponsiveContainer width="100%" height="100%"><BarChart data={funnel?.channels || []}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="channel"/><YAxis/><Tooltip/><Legend/><Bar dataKey="registered" fill="#0f766e"/><Bar dataKey="verified" fill="#0284c7"/><Bar dataKey="first_booking" fill="#7c3aed"/><Bar dataKey="repeat" fill="#d97706"/></BarChart></ResponsiveContainer></div><div className="mt-4 overflow-x-auto"><table className="min-w-full text-right text-sm"><thead><tr className="border-b text-slate-500"><th className="p-2">القناة</th><th className="p-2">مسجلون</th><th className="p-2">متحققون</th><th className="p-2">أول طلب</th><th className="p-2">تكرار</th><th className="p-2">تحويل أول طلب</th></tr></thead><tbody>{funnel?.channels.map((row) => <tr key={row.channel} className="border-b"><td className="p-2">{row.channel}</td><td className="p-2">{row.registered}</td><td className="p-2">{row.verified}</td><td className="p-2">{row.first_booking}</td><td className="p-2">{row.repeat}</td><td className="p-2">{row.conv_first_pct ?? '—'}%</td></tr>)}</tbody></table></div></article><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">احتفاظ cohorts وLTV</h2><div className="mt-4 overflow-x-auto"><table className="min-w-full text-right text-sm"><thead><tr className="border-b text-slate-500"><th className="p-2">cohort</th><th className="p-2">الحجم</th><th className="p-2">D1</th><th className="p-2">D7</th><th className="p-2">D30</th><th className="p-2">LTV للدافعين</th></tr></thead><tbody>{cohorts?.cohorts.map((row) => <tr key={row.cohort} className="border-b"><td className="p-2">{row.cohort}</td><td className="p-2">{row.size}</td><td className="p-2">{row.d1}%</td><td className="p-2">{row.d7}%</td><td className="p-2">{row.d30}%</td><td className="p-2">{row.ltv_avg_payers} ر.س</td></tr>)}</tbody></table></div></article><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">دوري المزودين</h2><div className="mt-4 overflow-x-auto"><table className="min-w-full text-right text-sm"><thead><tr className="border-b text-slate-500"><th className="p-2">المزوّد</th><th className="p-2">العمودي</th><th className="p-2">GMV</th><th className="p-2">الإكمال</th><th className="p-2">الإلغاء</th><th className="p-2">التقييم</th></tr></thead><tbody>{league.map((row) => <tr key={`${row.kind}:${row.provider_id}`} className="border-b"><td className="p-2">{row.provider_name}</td><td className="p-2">{row.kind}</td><td className="p-2">{row.gmv} ر.س</td><td className="p-2">{row.completion_rate_pct}%</td><td className="p-2">{row.cancel_rate_pct}%</td><td className="p-2">{row.avg_rating ?? '—'} ({row.ratings_count})</td></tr>)}</tbody></table></div></article><div className="grid gap-6 lg:grid-cols-2"><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">فرص الكتالوج من البحث</h2><div className="mt-4 grid gap-4 md:grid-cols-2"><div><h3 className="font-medium">أكثر عمليات البحث</h3><ul className="mt-2 space-y-2 text-sm">{search?.top_queries.map((item, index) => <li key={`${item._id}:${index}`} className="flex justify-between border-b pb-1"><span>{item._id || '—'}</span><strong>{item.count}</strong></li>)}</ul></div><div><h3 className="font-medium">نتائج صفرية</h3><ul className="mt-2 space-y-2 text-sm">{search?.zero_result_opportunities.map((item, index) => <li key={`${item._id}:${index}`} className="flex justify-between border-b pb-1"><span>{item._id || '—'}</span><strong>{item.count}</strong></li>)}</ul></div></div></article><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">NPS والتنبيهات</h2><p className="mt-3 text-3xl font-bold text-teal-700">{nps?.nps ?? '—'}</p><p className="text-sm text-slate-500">NPS من {nps?.total ?? 0} تقييم</p><div className="mt-4 grid grid-cols-3 gap-2 text-center text-sm"><div className="rounded bg-teal-50 p-2">مروجون<strong className="block">{nps?.promoters ?? 0}</strong></div><div className="rounded bg-slate-50 p-2">محايدون<strong className="block">{nps?.passives ?? 0}</strong></div><div className="rounded bg-rose-50 p-2">منتقدون<strong className="block">{nps?.detractors ?? 0}</strong></div></div><h3 className="mt-5 font-medium">تنبيهات z-score ({anomalies?.window_days} يوماً)</h3><ul className="mt-2 space-y-2 text-sm">{[...(anomalies?.cancellation_anomalies || []).map((r) => ({ ...r, type: 'إلغاء' })), ...(anomalies?.payment_failure_anomalies || []).map((r) => ({ ...r, type: 'فشل دفع' }))].map((item, index) => <li key={`${item.type}:${item.date}:${index}`} className="rounded bg-amber-50 p-2">{item.type} · {item.date} · {item.value} · z={item.z}</li>)}</ul></article></div></>}</section></>;
}
